-- Local fixture only; validates acknowledged announcement -> unapproved knowledge draft.
begin;
create temporary table akf(actor uuid,viewer uuid,wid uuid,sid uuid,meeting uuid,request uuid,source uuid,content uuid);
insert into akf values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id) select actor from akf union all select viewer from akf;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,actor,'Announcement fixture' from akf;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,actor,'owner' from akf union all select wid,viewer,'viewer' from akf;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Announcement site','native_business','business','active',actor from akf;
create function pg_temp.aexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on akf to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from akf),true);
select public.bz_agency_command(wid,sid,jsonb_build_object('action','meeting','id',meeting,'agenda','We are adding a reviewed automation service.','mode','announcement','participants',jsonb_build_array('content'),'reviewed',true,'inputMode','corrected-transcript')) from akf;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','accept-decision','id',meeting,'expectedVersion',1,'reason','Prepare this verified service update for private use.','reviewed',true)) from akf;
select public.bz_distribute_meeting_request(wid,sid,jsonb_build_object('id',meeting,'requestId',request,'expectedVersion',2,'instruction','Prepare private channel drafts from the verified announcement.','channels',jsonb_build_array('blog'),'reviewed',true)) from akf;
reset role;
insert into bizoveya_private.site_agent_rosters(site_id,version,document,actor_id) select sid,1,jsonb_build_object('enabled',true,'agents',jsonb_build_array(jsonb_build_object('kind','content','agentId',content,'agentVersion',1))),actor from akf;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from akf),true);
select public.bz_invite_meeting_participants(wid,sid,jsonb_build_object('id',meeting,'expectedVersion',3,'reviewed',true)) from akf;
select pg_temp.aexpect(format('select public.bz_prepare_announcement_knowledge(%L,%L,%L)',wid,sid,jsonb_build_object('action','prepare-announcement-knowledge','meetingId',meeting,'sourceId',source,'expectedVersion',4,'document',jsonb_build_object('title','Automation service announcement','filename','','sourceText','Founder-reviewed announcement: a new automation service is planned.','facts',jsonb_build_array(jsonb_build_object('id','service-update','text','A reviewed automation service update is being prepared.'))),'reviewed',true)),'bz_meeting_receipts_required') from akf;
reset role;
update bizoveya_private.meeting_participant_invitations set state='acknowledged',responded_at=clock_timestamp(),note='Pinned worker acknowledged the versioned announcement.' where meeting_id=(select meeting from akf);
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from akf),true);
select public.bz_prepare_announcement_knowledge(wid,sid,jsonb_build_object('action','prepare-announcement-knowledge','meetingId',meeting,'sourceId',source,'expectedVersion',4,'document',jsonb_build_object('title','Automation service announcement','filename','','sourceText','Founder-reviewed announcement: a new automation service is planned.','facts',jsonb_build_array(jsonb_build_object('id','service-update','text','A reviewed automation service update is being prepared.'))),'reviewed',true)) from akf;
select public.bz_prepare_announcement_knowledge(wid,sid,jsonb_build_object('action','prepare-announcement-knowledge','meetingId',meeting,'sourceId',source,'expectedVersion',4,'document',jsonb_build_object('title','Automation service announcement','filename','','sourceText','Founder-reviewed announcement: a new automation service is planned.','facts',jsonb_build_array(jsonb_build_object('id','service-update','text','A reviewed automation service update is being prepared.'))),'reviewed',true)) from akf;
select set_config('request.jwt.claim.sub',(select viewer::text from akf),true);
select pg_temp.aexpect(format('select public.bz_prepare_announcement_knowledge(%L,%L,%L)',wid,sid,jsonb_build_object('action','prepare-announcement-knowledge','meetingId',meeting,'sourceId',gen_random_uuid(),'expectedVersion',5,'document',jsonb_build_object('title','Forged','filename','','sourceText','Forged source text.','facts','[]'::jsonb),'reviewed',true)),'bz_forbidden') from akf;
select pg_temp.aexpect('select * from bizoveya_private.announcement_knowledge_handoffs','permission denied');
reset role;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select meeting from akf));if j#>>'{announcementKnowledgeDraft,sourceId}'<>(select source::text from akf) or j#>>'{announcementKnowledgeDraft,createdUnapproved}'<>'true' or j#>>'{announcementKnowledgeDraft,currentApproved}'<>'false' or j#>>'{announcementKnowledgeDraft,sourceVersion}'<>'1' or j#>>'{announcementKnowledgeDraft,factCount}'<>'1' then raise exception 'Announcement knowledge projection mismatch';end if;if (select count(*) from public.bizoveya_knowledge_sources where id=(select source from akf) and not approved and version=1)<>1 or (select count(*) from bizoveya_private.announcement_knowledge_handoffs)<>1 or (select version from bizoveya_private.agency_records where id=(select meeting from akf))<>5 then raise exception 'Announcement knowledge retry or draft state mismatch';end if;if exists(select 1 from bizoveya_private.generation_runs) then raise exception 'Announcement knowledge handoff executed work';end if;end;$$;
set local role authenticated;select set_config('request.jwt.claim.sub',(select actor::text from akf),true);select public.bz_mutate_knowledge(wid,sid,source,'approve',null,1) from akf;reset role;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select meeting from akf));if j#>>'{announcementKnowledgeDraft,createdUnapproved}'<>'true' or j#>>'{announcementKnowledgeDraft,currentApproved}'<>'true' or j#>>'{announcementKnowledgeDraft,sourceVersion}'<>'2' then raise exception 'Separate knowledge approval was not projected truthfully';end if;end;$$;
select pg_temp.aexpect('update bizoveya_private.announcement_knowledge_handoffs set decision=''forged''','bz_immutable_agency_handoff');
rollback;
